// ELEMENTS:
// 1. Foto do imóvel em ecrã inteiro (src), fade + push-in lento
// 2. Gradientes navy transparentes no topo e no rodapé
// 3. Topo: logótipo (logo) ou marca (logoText) à esquerda, estado (tag) à direita, tracking largo
// 4. Barra coral + localização (location) a branco
// 5. Título em serifa (title / anim.text)
// 6. Factos (facts) em ink
// 7. Rodapé: retrato redondo do agente (avatar) + nome (name) + telefone (cta) numa pílula branca
// 8. Linha legal (legal)
// 9. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY_RGB = "0,31,68";
const CYAN = "#DE212B";
const CORAL = "#DE212B";
const INK = "#001F44";
const WHITE = "#FFFFFF";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.26) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.1, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

// All-caps copy from the planner reads as shouting in a serif: keep it, but sentence-case it.
const calm = (s: string): string => (s.length > 3 && s === s.toUpperCase() ? s.charAt(0) + s.slice(1).toLowerCase() : s);

const ImovelNovoRevelacao: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const land = format === "landscape";
  const u = land ? H / 1080 : format === "half" ? (H / 960) * 0.85 : W / 1080;
  const T = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const s = (k: string): string => (typeof p[k] === "string" || typeof p[k] === "number" ? String(p[k]).trim() : "");

  const src = s("src");
  const brand = s("logoText") || "RE/MAX";
  const tag = s("tag");
  const location = s("location");
  const title = calm(s("title") || String(anim.text ?? "").trim());
  const facts = s("facts");
  const name = s("name");
  const avatar = s("avatar");
  const logo = s("logo");
  const phone = s("cta").replace(/^ligue( já)?\s*/i, "");
  const legal = s("legal");

  const scale = interpolate(f, [0, T], [1.02, 1.1], { ...clamp, easing: Easing.inOut(Easing.sin) });
  const fadeIn = interpolate(f, [0, Math.round(0.5 * fps)], [0, 1], clamp);
  const rise = (delay: number): React.CSSProperties => {
    const t = interpolate(f, [Math.round(delay * fps), Math.round((delay + 0.7) * fps)], [0, 1], { ...clamp, easing: EASE });
    return { opacity: t, transform: `translateY(${(1 - t) * 24 * u}px)` };
  };
  const bar = interpolate(f, [Math.round(0.35 * fps), Math.round(0.95 * fps)], [0, 72 * u], { ...clamp, easing: EASE });
  const titleSize = Math.min(108 * u, ((W - 144 * u) / Math.max(8, title.length * 0.42)) * (land ? 1 : 2.4));

  const label: React.CSSProperties = { fontFamily: FONTS.body, fontSize: 36 * u, letterSpacing: "0.22em", textTransform: "uppercase" };

  return (
    <AbsoluteFill style={{ textShadow: "0 2px 18px rgba(0,0,0,0.45)", overflow: "hidden", backgroundColor: INK }}>
      <AbsoluteFill style={{ opacity: fadeIn, transform: `scale(${scale})` }}>
        {src ? <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover", filter: "saturate(0.88) contrast(1.05)" }} /> : null}
      </AbsoluteFill>
      <AbsoluteFill
        style={{
          background: `linear-gradient(180deg, rgba(${NAVY_RGB},0.6) 0%, rgba(${NAVY_RGB},0) 22%, rgba(${NAVY_RGB},0) ${land ? 30 : 42}%, rgba(${NAVY_RGB},0.94) 100%)`,
        }}
      />

      <div style={{ position: "absolute", top: 80 * u, left: 72 * u, right: 72 * u, display: "flex", justifyContent: "space-between", alignItems: "center", color: WHITE, ...rise(0.2) }}>
        {logo ? <Img src={logo} style={{ height: 72 * u, width: "auto", objectFit: "contain" }} /> : <div style={{ ...label, fontWeight: 800, textTransform: "none", letterSpacing: "0.04em", fontSize: 44 * u }}>{brand}</div>}
        {tag ? <div style={{ ...label, fontWeight: 600, background: CORAL, color: WHITE, textShadow: "none", borderRadius: 4 * u, padding: `${10 * u}px ${18 * u}px` }}>{tag}</div> : null}
      </div>

      <div
        style={{
          position: "absolute",
          left: 72 * u,
          right: 72 * u,
          bottom: (land ? 64 : 150) * u,
          display: "flex",
          flexDirection: "column",
          gap: 30 * u,
          color: WHITE,
        }}
      >
        {location ? (
          <div style={{ display: "flex", alignItems: "center", gap: 28 * u }}>
            <div style={{ width: bar, height: 4 * u, background: CYAN, flexShrink: 0 }} />
            <div style={{ ...label, fontSize: 38 * u, fontWeight: 600, ...rise(0.4) }}>{location}</div>
          </div>
        ) : null}
        {title ? (
          <div style={{ fontFamily: FONTS.display, fontVariantNumeric: "lining-nums", fontWeight: 300, fontSize: titleSize, lineHeight: 1.02, ...rise(0.55) }}>{title}</div>
        ) : null}
        {facts ? <div style={{ ...label, fontSize: 40 * u, letterSpacing: "0.16em", fontWeight: 600, color: WHITE, ...rise(0.75) }}>{facts}</div> : null}
        {name || phone || avatar ? (
          <div style={{ display: "flex", alignItems: "center", gap: 28 * u, marginTop: 10 * u, ...rise(0.95) }}>
            {avatar ? <Img src={avatar} style={{ width: 150 * u, height: 150 * u, borderRadius: 999, objectFit: "cover", objectPosition: "center top", border: `${3 * u}px solid ${WHITE}`, flexShrink: 0 }} /> : null}
            <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 14 * u }}>
            {name ? <div style={{ fontFamily: FONTS.display, fontVariantNumeric: "lining-nums", fontWeight: 300, fontSize: 56 * u, lineHeight: 1.05, letterSpacing: "0.04em" }}>{name}</div> : null}
            {phone ? (
              <div style={{ background: CORAL, color: WHITE, textShadow: "none", borderRadius: 999, padding: `${16 * u}px ${28 * u}px`, fontFamily: FONTS.body, fontWeight: 600, fontSize: 42 * u, letterSpacing: "0.06em", whiteSpace: "nowrap" }}>
                {phone}
              </div>
            ) : null}
            </div>
          </div>
        ) : null}
        {legal ? <div style={{ ...label, fontSize: 30 * u, letterSpacing: "0.2em", color: WHITE, ...rise(1.1) }}>{legal}</div> : null}
      </div>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: "#DE212B" }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default ImovelNovoRevelacao;

