import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { COLORS, FONTS, textForBg } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const CLAMP = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const ImovelNovoRevelacao: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const frame = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const str = (k: string) => (p[k] == null ? "" : String(p[k]).trim());

  const src = String(anim.params?.src ?? "");
  const avatar = String(anim.params?.avatar ?? "");
  const logo = String(anim.params?.logo ?? "");
  const tag = str("tag");
  const price = str("price");
  const location = str("location");
  const title = str("title") || String(anim.text ?? "").trim();
  const facts = str("facts");
  const phone = str("phone");
  const name = str("name");
  const legal = str("legal");

  const side = format !== "portrait";
  const s =
    format === "portrait"
      ? Math.min(W / 1080, H / 1920)
      : format === "half"
        ? Math.min(W / 1080, H / 960) * 0.6
        : Math.min(W / 1920, H / 1080) * 0.82;
  const m = Math.max(72 * s, W * 0.04);

  // Compress the build-up for short layers so the finished layout always gets to hold.
  const lenSec = Math.max(0.5, anim.end - anim.start);
  const k = Math.min(1, lenSec / 3.2);
  const at = (t: number) => t * k * fps;
  const bounce = (t: number, damping = 11) =>
    spring({ frame: frame - at(t), fps, config: { damping, mass: 0.7, stiffness: 140 } });
  const fadeIn = (t: number) => interpolate(frame, [at(t), at(t) + 0.3 * fps * k + 1], [0, 1], CLAMP);
  const rise = (t: number, dist = 50): React.CSSProperties => ({
    opacity: fadeIn(t),
    translate: `0 ${(1 - bounce(t, 12)) * dist * s}px`,
  });

  const panelBg = COLORS.teal;
  const onPanel = textForBg(panelBg);
  const pillBg = COLORS.gold;
  const onPill = textForBg(pillBg);
  const tagBg = COLORS.papyrus;
  const onTag = textForBg(tagBg);
  const well = "rgba(255,255,255,.22)";

  // Geometry: portrait = photo on top, panel below with a slash rising right;
  // half/landscape = photo left, panel right with a slanted seam.
  const panelTop = H * 0.555;
  const depth = W * 0.075;
  const pw = W * (format === "half" ? 0.46 : 0.5);
  const slashX = H * 0.12;

  const photoStyle: React.CSSProperties = side
    ? { left: 0, top: 0, width: pw, height: H }
    : { left: 0, top: 0, width: W, height: panelTop + depth };
  const panelStyle: React.CSSProperties = side
    ? { left: pw - slashX, top: 0, width: W - pw + slashX, height: H, clipPath: `polygon(${slashX}px 0, 100% 0, 100% 100%, 0 100%)` }
    : { left: 0, top: panelTop, width: W, height: H - panelTop, clipPath: `polygon(0 ${depth}px, 100% 0, 100% 100%, 0 100%)` };

  const reveal = interpolate(frame, [0, at(0.9)], [0, 1], { ...CLAMP, easing: Easing.bezier(0.65, 0, 0.35, 1) });
  const panelIn = bounce(0.7, 16);
  const tagIn = bounce(0.55, 10);
  const priceIn = bounce(1.0, 9);
  const pillIn = bounce(1.45, 9);
  const avatarIn = bounce(1.6, 9);

  const display: React.CSSProperties = {
    fontFamily: FONTS.display,
    fontWeight: FONTS.displayWeight,
    fontStyle: "italic",
    lineHeight: 1,
  };

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.body, fontWeight: FONTS.bodyWeight }}>
      {/* Hero photo — wipes in top-down while settling from a slight zoom */}
      <div
        style={{
          position: "absolute",
          ...photoStyle,
          overflow: "hidden",
          clipPath: `inset(0 0 ${(1 - reveal) * 100}% 0)`,
        }}
      >
        {src ? (
          <Img
            src={src}
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
              scale: interpolate(frame, [0, at(1.8)], [1.18, 1], { ...CLAMP, easing: Easing.bezier(0.16, 1, 0.3, 1) }),
            }}
          />
        ) : (
          <div
            style={{
              width: "100%",
              height: "100%",
              backgroundColor: COLORS.vellum,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              color: COLORS.mutedOnLight,
              fontSize: 28 * s,
              letterSpacing: "0.14em",
              textTransform: "uppercase",
            }}
          >
            Foto do imóvel
          </div>
        )}
      </div>

      {/* Status tag drops from above */}
      {tag ? (
        <div
          style={{
            position: "absolute",
            top: side ? H * 0.08 : H * 0.13,
            left: m,
            maxWidth: (side ? pw : W) - 2 * m,
            backgroundColor: pillBg,
            color: onPill,
            borderRadius: 999,
            padding: `${12 * s}px ${30 * s}px`,
            fontSize: 34 * s,
            textTransform: "uppercase",
            opacity: fadeIn(0.55),
            translate: `0 ${(1 - tagIn) * -300}%`,
            ...display,
          }}
        >
          {tag}
        </div>
      ) : null}

      {/* Primary panel slides up (portrait) / in from the right (side) */}
      <div
        style={{
          position: "absolute",
          ...panelStyle,
          backgroundColor: panelBg,
          color: onPanel,
          translate: side ? `${(1 - panelIn) * 100}% 0` : `0 ${(1 - panelIn) * 100}%`,
        }}
      >
        <div
          style={{
            position: "absolute",
            left: side ? slashX + m : m,
            right: m,
            top: side ? 0 : depth + H * 0.035,
            bottom: side ? 0 : undefined,
            display: "flex",
            flexDirection: "column",
            justifyContent: side ? "center" : "flex-start",
            gap: 20 * s,
            overflowWrap: "break-word",
          }}
        >
          {location ? (
            <div
              style={{
                fontSize: 26 * s,
                fontWeight: 600,
                letterSpacing: "0.14em",
                textTransform: "uppercase",
                ...rise(1.1),
              }}
            >
              {location}
            </div>
          ) : null}
          {title ? (
            <div
              style={{
                ...display,
                fontSize: 90 * s * Math.max(0.55, Math.min(1, 16 / Math.max(1, title.length))),
                lineHeight: 0.98,
                textTransform: "uppercase",
                ...rise(1.2, 70),
              }}
            >
              {title}
            </div>
          ) : null}
          {facts ? (
            <div style={{ fontSize: 32 * s, fontWeight: 500, lineHeight: 1.4, ...rise(1.3) }}>{facts}</div>
          ) : null}
          {phone ? (
            <div
              style={{
                alignSelf: "flex-start",
                maxWidth: "100%",
                marginTop: 12 * s,
                backgroundColor: pillBg,
                color: onPill,
                borderRadius: 999,
                padding: `${14 * s}px ${36 * s}px`,
                fontSize: 44 * s,
                ...display,
                opacity: fadeIn(1.45),
                scale: pillIn,
                transformOrigin: "left center",
              }}
            >
              {phone}
            </div>
          ) : null}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 20 * s,
              marginTop: 24 * s,
              ...rise(1.6),
            }}
          >
            <div
              style={{
                width: 84 * s,
                height: 84 * s,
                flexShrink: 0,
                borderRadius: "50%",
                border: `${4 * s}px solid ${onPanel}`,
                overflow: "hidden",
                backgroundColor: well,
                scale: avatarIn,
              }}
            >
              {avatar ? <Img src={avatar} style={{ width: "100%", height: "100%", objectFit: "cover" }} /> : null}
            </div>
            <div style={{ flex: 1, fontSize: 30 * s, fontWeight: 700, lineHeight: 1.2 }}>{name}</div>
            <div style={{ flexShrink: 0, opacity: fadeIn(1.75), translate: `0 ${(1 - bounce(1.75, 12)) * -40 * s}px` }}>
              {logo ? (
                <Img src={logo} style={{ height: 70 * s, width: "auto", display: "block" }} />
              ) : (
                <div style={{ width: 120 * s, height: 70 * s, backgroundColor: well }} />
              )}
            </div>
          </div>
          {legal ? (
            <div
              style={{
                fontSize: 18 * s,
                fontWeight: 600,
                letterSpacing: "0.04em",
                textTransform: "uppercase",
                ...rise(1.8, 30),
              }}
            >
              {legal}
            </div>
          ) : null}
        </div>
      </div>

      {/* Price tag pops onto the seam */}
      {price ? (
        <div
          style={{
            position: "absolute",
            ...(side
              ? { right: W - pw + slashX * 0.2, bottom: H * 0.08, maxWidth: pw - m }
              : { right: m, top: panelTop, translate: "0 -80%", maxWidth: W - 2 * m }),
            backgroundColor: tagBg,
            color: onTag,
            padding: `${14 * s}px ${34 * s}px`,
            fontSize: 72 * s,
            ...display,
            opacity: fadeIn(1.0),
            scale: priceIn,
          }}
        >
          {price}
        </div>
      ) : null}
    </AbsoluteFill>
  );
};

export default ImovelNovoRevelacao;

