import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const BLUE = "#05B8E6";
const CORAL = "#F06052";
const INK = "#213D56";
const WHITE = "#FFFFFF";
const PHOTO_BG = "#EEF0EF";
const AVATAR_BG = "#B4B7B8";

// Font size that keeps `text` within `avail` px (rough glyph-width estimate).
const fit = (text: string, base: number, avail: number, k = 0.62): number =>
  Math.min(base, avail / (Math.max(1, text.length) * k));

const ImovelNovoStory: React.FC<PrimitiveProps> = ({ anim, fps, format, frame }) => {
  const f = useCurrentFrame();
  const W = frame.width;
  const H = frame.height;
  const L = Math.max(1, Math.round((anim.end - anim.start) * fps));

  const p = anim.params ?? {};
  const str = (k: string): string => {
    const v = (p as Record<string, unknown>)[k];
    return v == null ? "" : String(v).trim();
  };
  const src = String(anim.params?.src ?? "");
  const avatar = String(anim.params?.avatar ?? "");
  const logo = String(anim.params?.logo ?? "");
  const tag = str("tag");
  const price = str("price");
  const location = str("location");
  const title = str("title") || String(anim.text ?? "").trim();
  const facts = str("facts");
  const cta = str("cta");
  const name = str("name");
  const logoText = str("logoText");
  const logoSub = str("logoSub");
  const legal = str("legal");

  const side = format !== "portrait";
  const u =
    format === "portrait"
      ? W / 1080
      : format === "half"
        ? Math.min(W / 1080, H / 960) * 0.78
        : Math.min(W / 1920, H / 1080);

  // Staggered springs; each settles 12% of the layer after it starts, so all is still by 60%.
  const dur = Math.max(1, Math.round(0.12 * L));
  const at = (start: number, bouncy = true): number =>
    spring({
      frame: f - Math.round(start * L),
      fps,
      durationInFrames: dur,
      config: bouncy ? { damping: 9, stiffness: 140, mass: 0.8 } : { damping: 200 },
    });
  const fade = (s: number): number => Math.max(0, Math.min(1, s * 2));

  const reveal = interpolate(f, [0, Math.max(1, Math.round(0.2 * L))], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.16, 1, 0.3, 1),
  });
  const sPanel = at(0.15, false);
  const sTag = at(0.2);
  const sPrice = at(0.28);
  const sEyebrow = at(0.3, false);
  const sTitle = at(0.34);
  const sFacts = at(0.38, false);
  const sCta = at(0.42);
  const sAvatar = at(0.46);
  const sLogo = at(0.48);
  const sLegal = at(0.48, false);

  // Geometry per arrangement.
