            : "polygon(0 62.2%, 100% 57.2%, 100% 100%, 0 100%)",
          transform: side ? `translateX(${(1 - sPanel) * 70}%)` : `translateY(${(1 - sPanel) * 50}%)`,
        }}
      />

      {/* 2. Status pill */}
      {tag ? (
        <div
          style={{
            position: "absolute",
            left: side ? margin : 0.066 * W,
            top: side ? 0.08 * H : 0.129 * H,
            maxWidth: side ? seamTop - 2 * margin : W * 0.8,
            backgroundColor: CORAL,
            color: WHITE,
            borderRadius: 999,
            padding: `${14 * u}px ${34 * u}px`,
            fontSize: 40 * u,
            lineHeight: 1,
            ...headline,
            opacity: fade(sTag),
            transform: `translateY(${(1 - sTag) * -180 * u}px)`,
          }}
        >
          {tag}
        </div>
      ) : null}

      {/* 4. Price tag on the seam */}
      {price ? (
        <div
          style={{
            position: "absolute",
            right: side ? W - (pw * W + d - 2 * d * 0.74) - 60 * u : 0.066 * W,
            top: side ? 0.74 * H : 0.541 * H,
            maxWidth: priceAvail,
            backgroundColor: WHITE,
            color: INK,
            padding: `${20 * u}px ${40 * u}px`,
            fontSize: priceSize,
            lineHeight: 1,
            textAlign: "center",
            fontFamily: FONTS.display,
            fontWeight: 800,
            fontStyle: "italic",
            transform: `scale(${Math.max(0, sPrice)})`,
            transformOrigin: "right center",
          }}
        >
          {price}
        </div>
      ) : null}

      {/* 5–12. Panel content */}
      <div
        style={{
          position: "absolute",
          left: contentLeft,
          right: contentRight,
          top: side ? 0 : 0.635 * H,
          bottom: side ? 0 : undefined,
          display: "flex",
          flexDirection: "column",
          justifyContent: side ? "center" : "flex-start",
          color: WHITE,
        }}
      >
        {location ? (
          <div
            style={{
              fontFamily: FONTS.body,
              fontWeight: 600,
              textTransform: "uppercase",
              letterSpacing: "0.14em",
              fontSize: 30 * u,
              lineHeight: 1,
              marginBottom: 16 * u,
              opacity: fade(sEyebrow),
              transform: `translateY(${(1 - sEyebrow) * 50 * u}px)`,
            }}
          >
            {location}
          </div>
        ) : null}
        {title ? (
          <div
            style={{
              ...headline,
              fontSize: titleSize,
              lineHeight: 0.98,
              overflowWrap: "break-word",
              marginBottom: 16 * u,
              opacity: fade(sTitle),
              transform: `translateY(${(1 - sTitle) * 80 * u}px)`,
            }}
          >
            {title}
          </div>
        ) : null}
        {facts ? (
          <div
            style={{
              fontFamily: FONTS.body,
              fontWeight: 500,
              fontSize: 36 * u,
              lineHeight: 1.4,
              marginBottom: 28 * u,
              opacity: fade(sFacts),
              transform: `translateY(${(1 - sFacts) * 50 * u}px)`,
            }}
          >
            {facts}
          </div>
        ) : null}
        {cta ? (
          <div
            style={{
              alignSelf: "flex-start",
              maxWidth: "100%",
              backgroundColor: CORAL,
              borderRadius: 999,
              padding: `${18 * u}px ${ctaPad}px`,
              fontFamily: FONTS.display,
              fontWeight: 800,
              fontStyle: "italic",
              fontSize: ctaSize,
              lineHeight: 1.05,
              marginBottom: 34 * u,
              transform: `scale(${Math.max(0, sCta)})`,
              transformOrigin: "left center",
            }}
          >
            {cta}
          </div>
        ) : null}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            gap: 24 * u,
            marginBottom: 28 * u,
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 22 * u,
              opacity: fade(sAvatar),
              transform: `translateY(${(1 - sAvatar) * 70 * u}px)`,
            }}
          >
            <div
              style={{
                width: 74 * u,
                height: 74 * u,
                flexShrink: 0,
                borderRadius: "50%",
                border: `${4 * u}px solid ${WHITE}`,
                backgroundColor: AVATAR_BG,
                overflow: "hidden",
                boxSizing: "border-box",
              }}
            >
              {avatar ? (
                <Img src={avatar} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
              ) : null}
            </div>
            {name ? (
              <div style={{ fontFamily: FONTS.body, fontWeight: 700, fontSize: 34 * u, lineHeight: 1.2 }}>
                {name}
              </div>
            ) : null}
          </div>
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              flexShrink: 0,
              opacity: fade(sLogo),
              transform: `translateY(${(1 - sLogo) * -60 * u}px) scale(${Math.max(0, sLogo)})`,
            }}
          >
            {logo ? (
              <Img src={logo} style={{ height: 70 * u, width: "auto" }} />
            ) : (
              <>
                {logoText ? (
                  <div style={{ fontFamily: FONTS.body, fontWeight: 800, fontSize: 60 * u, lineHeight: 0.9, letterSpacing: "-0.02em" }}>
                    {logoText}
                  </div>
                ) : null}
                {logoSub ? (
                  <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 12 * u, lineHeight: 1.2, letterSpacing: "0.08em" }}>
                    {logoSub}
                  </div>
                ) : null}
              </>
            )}
          </div>
        </div>
        {legal ? (
          <div
            style={{
              fontFamily: FONTS.body,
              fontWeight: 600,
              textTransform: "uppercase",
              letterSpacing: "0.04em",
              fontSize: 19 * u,
              lineHeight: 1.2,
              opacity: fade(sLegal),
              transform: `translateY(${(1 - sLegal) * 30 * u}px)`,
            }}
          >
            {legal}
          </div>
        ) : null}
      </div>
    </AbsoluteFill>
  );
};

export default ImovelNovoStory;
